# -*- coding: utf-8 -*-
import re

with open('app/src/main/java/com/example/data/WorshipData.kt', 'r', encoding='utf-8') as f:
    content = f.read()

match = re.search(r'val sahifaSajjadiya = listOf\((.*?)\)\s+val generalPrayers =', content, re.DOTALL)
if not match:
    print("Could not find sahifaSajjadiya block!")
    exit(1)

block = match.group(1)
elements = re.split(r'(?=Pair\(\"الدعاء)', block)
elements = [e.strip() for e in elements if e.strip()]

for idx in range(len(elements)):
    elements[idx] = elements[idx].rstrip()
    if elements[idx].endswith(','):
        elements[idx] = elements[idx][:-1].rstrip()

text_11 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أَللَّهُمَّ إنَّهُ يَحْجُبُنِي عَنْ مَسْأَلَتِكَ خِلاَلٌ ثَلاثٌ وَتَحْدُونِي عَلَيْهَا خَلَّةٌ وَاحِدَةٌ، يَحْجُبُنِي أَمْرٌ أَمَرْتَ بِهِ فَأَبْطَأتُ عَنْهُ، وَنَهْيٌ نَهَيْتَنِي عَنْهُ فَأَسْرَعْتُ إلَيْهِ، وَنِعْمَةٌ أَنْعَمْتَ بِهَا عَلَيَّ فَقَصَّـرْتُ فِي شُكْرِهَـا.
وَيَحْدُونِي عَلَى مَسْأَلَتِكَ تَفَضُّلُكَ عَلَى مَنْ أَقْبَلَ بِوَجْهِهِ إلَيْكَ، وَوَفَدَ بِحُسْنِ ظَنِّـهِ إلَيْكَ، إذْ جَمِيعُ إحْسَانِكَ تَفَضُّلٌ، وَإذْ كُلُّ نِعَمِكَ ابْتِدَاءٌ.
فَهَا أَنَا ذَا يَا إلهِيْ وَاقِفٌ بِبَابِ عِزِّكَ وُقُوفَ المُسْتَسْلِمِ الذَّلِيْل، وَسَائِلُكَ عَلَى الْحَيَاءِ مِنّي سُؤَالَ الْبَائِسِ الْمُعِيْلِ.
مُقـرٌّ لَكَ بأَنّي لَمْ أَسْتَسْلِمْ وَقْتَ إحْسَانِـكَ إلاَّ بِالاِقْلاَعِ عَنْ عِصْيَانِكَ، وَلَمْ أَخْلُ فِي الْحَالاتِ كُلِّهَا مِنِ امْتِنَانِكَ.
فَهَلْ يَنْفَعُنِي يَا إلهِي إقْرَارِي عِنْدَكَ بِسُوءِ مَا اكْتَسَبْتُ؟ وَهَلْ يُنْجِيْنِي مِنْكَ اعْتِرَافِي لَكَ بِقَبِيْحِ مَا ارْتَكَبْتُ؟ أَمْ أَوْجَبْتَ لِي فِي مَقَامِي هَذَا سُخْطَكَ؟ أَمْ لَزِمَنِي فِي وَقْتِ دُعَائِي مَقْتُكَ؟
سُبْحَانَكَ! لاَ أَيْأَسُ مِنْكَ وَقَدْ فَتَحْتَ لِيَ بَابَ التَّوْبَةِ إلَيْكَ، بَلْ أَقُولُ مَقَالَ الْعَبْدِ الذَّلِيلِ الظَّالِمِ لِنَفْسِهِ الْمُسْتَخِفِّ بِحُرْمَةِ رَبِّهِ الَّذِي عَظُمَتْ ذُنُوبُهُ فَجَلَّتْ وَأَدْبَرَتْ أَيّامُهُ فَوَلَّتْ حَتَّى إذَا رَأى مُدَّةَ الْعَمَلِ قَدِ انْقَضَتْ وَغَايَةَ الْعُمُرِ قَدِ انْتَهَتْ، وَأَيْقَنَ أَنَّهُ لا مَحيصَ لَهُ مِنْكَ، وَلاَ مَهْرَبَ لَهُ عَنْكَ تَلَقَّاكَ بِالانَابَةِ،
وَأَخْلَصَ لَكَ التَّوْبَةَ، فَقَامَ إلَيْكَ بِقَلْبِ طَاهِر نَقِيٍّ ثُمَّ دَعَاكَ بِصَوْت حَائِل خَفِيٍّ، قَدْ تَطَأطَأَ لَكَ فَانْحَنى، وَنَكَّسَ رَأسَهُ فَانْثَنَى، قَدْ أَرْعَشَتْ خَشْيَتُهُ رِجْلَيْهِ، وَغَرَّقَتْ دُمُوعُهُ خَدَّيْهِ، يَدْعُوكَ بِيَا أَرْحَمَ الرَّاحِمِينَ وَيَا أَرْحَمَ مَنِ انْتَابَهُ الْمُسْتَرْحِمُونَ،
وَيَا أَعْطَفَ مَنْ أَطَافَ بِهِ الْمُسْتَغْفِرُونَ،
وَيَا مَنْ عَفْوُهُ أكْثَرُ مِنْ نِقْمَتِهِ، وَيَا مَنْ رِضَاهُ أَوْفَرُ مِنْ سَخَطِهِ،
وَيَا مَنْ تَحَمَّدَ إلَى خَلْقِهِ بِحُسْنِ التَّجاوُزِ، وَيَا مَنْ عَوَّدَ عِبادَهُ قَبُولَ الانَابَةِ،
وَيَا مَنِ اسْتَصْلَحَ فَاسِدَهُمْ بِالتَّوْبَةِ وَيَا مَنْ رَضِيَ مِنْ فِعْلِهِمْ بِالْيَسيرِ،
وَيَا مَنْ كَافى قَلِيْلَهُمْ بِالْكَثِيرِ، وَيَا مَنْ ضَمِنَ لَهُمْ إجَابَةَ الدُّعاءِ،
وَيَا مَنْ وَعَدَهُمْ عَلَى نَفْسِهِ بِتَفَضُّلِهِ حُسْنَ الْجَزاءِ،
مَا أَنَا بِأَعْصَى مَنْ عَصَاكَ فَغَفَرْتَ لَهُ،
وَمَا أَنَا بِأَلْوَمِ مَنِ اعْتَذَرَ إلَيْكَ فَقَبِلْتَ مِنْهُ،
وَمَا أَنَا بِأَظْلَمِ مَنْ تَابَ إلَيْكَ فَعُدْتَ عَلَيْهِ،
أَتُوبُ إلَيْكَ فِي مَقَامِي هَذَا تَوْبَةَ نَادِم عَلَى مَا فَرَطَ مِنْهُ مُشْفِق مِمَّا اجْتَمَعَ عَلَيْهِ خَالِصِ الْحَيَاءِ مِمَّا وَقَعَ فِيْهِ، عَالِم بِأَنَّ الْعَفْوَ عَنِ الذَّنْبِ الْعَظِيمِ لاَ يَتَعـاظَمُكَ، وَأَنَّ التَّجَـاوُزَ عَنِ الاثْمِ الْجَلِيْلِ لا يَسْتَصْعِبُكَ، وَأَنَّ احْتِمَالَ الْجنَايَاتِ الْفَـاحِشَةِ لا يَتَكَأَّدُكَ، وَأَنَّ أَحَبَّ عِبَادِكَ إلَيْكَ مَنْ تَرَكَ الاسْتِكْبَارَ عَلَيْكَ، وَجَانَبَ الاِصْرَارَ، وَلَزِمَ الاسْتِغْفَارَ.
وَأَنَا أَبْرَأُ إلَيْكَ مِنْ أَنْ أَسْتَكْبِرَ، وَأَعُوذُ بِكَ مِنْ أَنْ أصِـرَّ.
وَأَسْتَغْفِرُكَ لِمَا قَصَّرْتُ فِيهِ، وَأَسْتَعِينُ بِكَ عَلَى مَا عَجَزْتُ عَنْهُ.
اللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَهَبْ لِي مَا يَجبُ عَلَيَّ لَكَ، وَعَافِنِي مِمَّا أَسْتَوْجِبُهُ مِنْكَ، وَأجِرْنِي مِمَّا يَخَافُهُ أَهْلُ الاساءَةِ فَإنَّكَ مَلِيءٌ بِالْعَفْوِ، مَرْجُوٌّ لِلْمَغْفِرَةِ، مَعْرُوفٌ بِالتَّجَاوُزِ، لَيْسَ لِحَاجَتِي مَطْلَبٌ سِوَاكَ، وَلا لِذَنْبِي غَافِرٌ غَيْرُكَ، حَاشَاكَ وَلاَ أَخَافُ عَلَى نَفْسِي إلاّ إيَّاكَ إنَّكَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ.
صَلِّ عَلَى مُحَمَّد وَآلِ مُحَمَّد، وَاقْض حَاجَتِي وَأَنْجِحْ طَلِبَتِي، وَاغْفِرْ ذَنْبِي، وَآمِنْ خَوْفَ نَفْسِيْ إنَّكَ عَلَى كُلِّ شَيْء قَدِيرٌ وَذلِكَ عَلَيْكَ يَسِيرٌ آمِينَ رَبَّ الْعَالَمِينَ."""

text_10 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
يا مَنْ ذِكْرُهُ شَرَفٌ لِلذَّاكِرِينَ وَيَا مَنْ شُكْرُهُ فَوْزٌ لِلشَّاكِرِينَ، وَيَا مَنْ طَاعَتُهُ نَجَاةٌ لِلْمُطِيعِينَ، صَلِّ عَلَى مُحَمَّد وَآلِهِ وَاشْغَلْ قُلُوبَنَا بِذِكْرِكَ عَنْ كُلِّ ذِكْر، وَأَلْسِنَتَنَا بِشُكْرِكَ عَنْ كُلِّ شُكْر وَجَوَارِحَنَا بِطَاعَتِكَ عَنْ كُلِّ طَاعَة.
فَإنْ قَدَّرْتَ لَنَا فَرَاغاً مِنْ شُغُل فَاجْعَلْهُ فَرَاغَ سَلاَمَة لا تُدْرِكُنَا فِيهِ تَبِعَةٌ وَلاَ تَلْحَقُنَا فِيهِ سَاَمَةٌ حَتَّى يَنْصَرِفَ عَنَّا كُتَّابُ السَّيِّئَاتِ بِصَحِيفَة خَالِيَة مِنْ ذِكْرِ سَيِّئاتِنَا وَيَتَوَلّى كُتَّابُ الْحَسَنَاتِ عَنَّا مَسْرُورِينَ بِمَا كَتَبُوا مِنْ حَسَنَاتِنَا.
وَإذَا انْقَضَتْ أَيَّامُ حَيَاتِنَـا وَتَصَرَّمَتْ مُـدَدُ أَعْمَارِنَـا، وَاسْتَحْضَرَتْنَا دَعْوَتُكَ الَّتِي لاَ بُدَّ مِنْهَا وَمِنْ إجَابَتِهَا، فَصَلِّ عَلَى مُحَمَّد وَآلِهِ، وَاجْعَلْ خِتَامَ مَا تُحْصِي عَلَيْنَا كَتَبَةُ أَعْمَالِنَا تَوْبَةً مَقْبُولَةً لا تُوقِفُنَا بَعْدَهَا عَلَى ذَنْب اجْتَرَحْنَاهُ، وَلاَ مَعْصِيَة اقْتَرَفْنَاهَا، وَلاَ تَكْشِفْ عَنَّا سِتْراً سَتَرْتَهُ عَلَى رُؤُوسِ الاشْهَادِ يَوْمَ تَبْلُوأَخْبَارَ عِبَادِكَ إنَّكَ رَحِيمٌ بِمَنْ دَعَاكَ، وَمُسْتَجيبٌ لِمَنْ نَادَاكَ."""

text_9 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
اللّهُمَّ إن تَشَأْ تعفُ عَنّا فَبِفضْلِكَ، وَانْ تَشَأْ تُعَذِّبْنا فَبَعدْلِكَ.
فَسَهِّلْ لَنَا عَفْوَكَ بِمنِّكَ، وَأَجِرْنَا مِنْ عَذَابِكَ بِتَجاوُزكَ؛ فَإنَّهُ لاَطاقَةَ لَنَا بَعدِكَ، وَلاَنجاةَ لاحَد دُوْنَ عَفْوِكَ.
يا غَنِيَّ الاغْنياء، هَا نَحَنُ عِبادُكَ، وَأَنَا أَفْقَراء إليْكَ فَأجْبُرْ فاقَتَنا بِوُسْعِكَ، ولاتَقْطَعَ رَجَاء نابِمَنْعِكَ فَتَكُوْنَ قد أَشْقَيْتَ مَنِ اسْتَسْعَدَ بِكَ، وَجَرَمْتَ مَنِ آسْتَرْفَدَ فَضْلَكَ.
فَإلى مَنْ حيْنئذ مُنْقَلَبُنَا عَنْكَ، وإلى أيْنَ مَذهَبُنَا عن بَابِكَ؟
سُبْحَنَكَ إنَحْنُ المضْطُّرون الذّينَ أَوْجَبْتَ إجابَتَهُمْ، وَأهْلُ السُّوْء الذّيْنَ وَعَدْتَ الْكَشْفَ عَنْهُمْ.
وَأَشْبَـهُ الاَشْياءِ بِمَشِيَّتِـكَ، وَأَوْلَى الامُورِ بِكَ فِيْ عَظَمَتِكَ رَحْمَةُ مَنِ اسْتَرْحَمَكَ، وَغَوْثُ مَنِ اسْتَغَاثَ بِكَ، فَارْحَمْ تَضَرُّعَنَا إلَيْكَ، وَأَغْنِنَا إذْ طَرَحْنَـا أَنْفُسَنَا بَيْنَ يَـدَيْكَ. أللَّهُمَّ إنَّ الشَّيْطَانَ قَدْ شمِتَ بِنَا إذْ شَايَعْنَاهُ عَلَى مَعْصِيَتِكَ،
فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَلا تُشْمِتْهُ بِنَا بَعْدَ تَرْكِنَا إيَّاهُ لَكَ، وَرَغْبَتِنَا عَنْهُ إلَيْكَ."""

text_8 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَصَيِّرْنَـا إلَى مَحْبُوبِكَ مِنَ التَّوْبَةِ وَأَزِلْنَا عَنْ مَكْرُوهِكَ مِنَ الاصْرَارِ.
أللَّهُمَّ وَمَتَى وَقَفْنَا بَيْنَ نَقْصَيْنِ فِي دِين أَوْ دُنْيَا فَأَوْقِعِ النَّقْصَ بِأَسْرَعِهِمَا فَنَاءً، وَاجْعَلِ التّوْبَةَ فِي أَطْوَلِهِمَا بَقَاءً.
وَإذَا هَمَمْنَا بِهَمَّيْنِ يُرْضِيكَ أَحَدُهُمَا عَنَّا وَيُسْخِطُكَ الاخَرُ عَلَيْنَا، فَمِلْ بِنَا إلَى مَا يُرْضِيْكَ عَنَّا، وَأَوْهِنْ قُوَّتَنَا عَمَّا يُسْخِطُكَ عَلَيْنَا، وَلاَ تُخَلِّ فِي ذلِكَ بَيْنَ نُفُوسِنَا وَاخْتِيَارِهَا؛ فَإنَّهَا مُخْتَارَةٌ لِلْبَاطِلِ إلاَّ مَا وَفَّقْتَ أَمَّارَةٌ بالسُّوءِ إلاّ مَا رَحِمْتَ.
اللَّهمَّ وَإنَّكَ مِنَ الضَّعْفِ خَلَقْتَنَا، وَعَلَى الْوَهْنِ بَنَيْتَنَا، وَمِنْ مَهِين ابْتَدَأتَنَا، فَلاَ حَوْلَ لَنَا إلاّ بِقُوَّتِكَ وَلا قُوَّةَ لَنَا إلاّ بِقوَّتِكَ، ولاقُوَّةَ لنا إلاّ ابِعَوْنِكَ.
فَأيِّدْنَا بِتَوْفِيقِكَ وَسَدِّدْنَا بِتَسْدِيدِكَ وَأعْمِ أَبْصَارَ قُلُوبِنَا عَمَّا خَالَفَ مَحَبَّتَكَ وَلا تَجْعَلْ لِشَيْء مِنْ جَوَارِحِنَا نُفُوذاً فِي مَعْصِيَتِكَ.
اللَّهُمَّ فَصَلِّ عَلَى مُحَمَد وَآلِهِ وَاجْعَلْ هَمَسَاتِ قُلُوبِنَا وَحَرَكَاتِ أَعْضَائِنَا، وَلَمَحَاتِ أَعْيُنِنَا، وَلَهَجَاتِ ألسِنَتِنَا فِيْ مُوجِبَاتِ ثَوَابِكَ، حَتَّى لاَ تَفُوتَنَا حَسَنَةٌ نَسْتَحِقُّ بِهَا جَزَآءَكَ، وَلا تَبْقَى لَنَا سَيِّئـةٌ نَسْتَوْجِبُ بِهَا عِقَابَكَ."""


